import{_ as t,o,c as a,a2 as i}from"./chunks/framework.C4u7U0Dw.js";const _=JSON.parse('{"title":"第 17 章 打造 Skill：将方法论蒸馏为可执行 Skill（易懂版）","description":"","frontmatter":{},"headers":[],"relativePath":"easy/第17章 打造 Skill：将方法论蒸馏为可执行 Skill（易懂版）.md","filePath":"easy/第17章 打造 Skill：将方法论蒸馏为可执行 Skill（易懂版）.md"}'),r={name:"easy/第17章 打造 Skill：将方法论蒸馏为可执行 Skill（易懂版）.md"};function s(e,l,n,k,u,g){return o(),a("div",null,[...l[0]||(l[0]=[i('<h1 id="第-17-章-打造-skill-将方法论蒸馏为可执行-skill-易懂版" tabindex="-1">第 17 章 打造 Skill：将方法论蒸馏为可执行 Skill（易懂版） <a class="header-anchor" href="#第-17-章-打造-skill-将方法论蒸馏为可执行-skill-易懂版" aria-label="Permalink to &quot;第 17 章 打造 Skill：将方法论蒸馏为可执行 Skill（易懂版）&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">📖 想读完整版？</p><p>这页是<strong>易懂版</strong>，用大白话讲重点。想系统学习，请读 [第 17 章 打造 Skill：将方法论蒸馏为可执行 Skill（完整版）](../../bluebook/第三篇 进阶篇：把案例变成自己的工作系统/第 17 章 打造 Skill：将方法论蒸馏为可执行 Skill.md)。</p></div><h2 id="这章讲什么-一句话" tabindex="-1">这章讲什么（一句话） <a class="header-anchor" href="#这章讲什么-一句话" aria-label="Permalink to &quot;这章讲什么（一句话）&quot;">​</a></h2><p><strong>从&quot;用别人的 Skill&quot;升级到&quot;把自己的干活经验做成 Skill&quot;——让你团队里每个人的经验都沉淀下来。</strong></p><h2 id="先打个比方" tabindex="-1">先打个比方 <a class="header-anchor" href="#先打个比方" aria-label="Permalink to &quot;先打个比方&quot;">​</a></h2><p>老师傅带徒弟，不是一句&quot;你看着办&quot;，而是把流程写下来：<strong>怎么问需求、怎么选料、怎么验成品</strong>。这份&quot;流程单&quot;就是 Skill。</p><p>打造 Skill = <strong>把你的方法论写下来，让它可执行、可复用。</strong></p><h2 id="核心就-3-件事" tabindex="-1">核心就 3 件事 <a class="header-anchor" href="#核心就-3-件事" aria-label="Permalink to &quot;核心就 3 件事&quot;">​</a></h2><ol><li><strong>选对对象</strong>：挑一件你<strong>重复做、做得好、有套路</strong>的事——周报、方案、数据清洗……</li><li><strong>拆出步骤</strong>：把&quot;你怎么做的&quot;拆成步骤：<strong>先做什么、看什么、判断什么、产出什么</strong>。</li><li><strong>写成模板</strong>：每个 Skill 包含 说明（干嘛用）+ 步骤（怎么做）+ 模板（长什么样）+ 检查点（怎么验）。</li></ol><h2 id="打造-skill-四步法" tabindex="-1">打造 Skill 四步法 <a class="header-anchor" href="#打造-skill-四步法" aria-label="Permalink to &quot;打造 Skill 四步法&quot;">​</a></h2><ol><li><strong>回放</strong>：回忆你上次做这事，从第一步到最后一步写了什么；</li><li><strong>提炼</strong>：去掉偶然因素，留下&quot;每次都一样&quot;的部分；</li><li><strong>固化</strong>：写成清单/模板，让新人照着就能做；</li><li><strong>试跑</strong>：用真实任务试一次，哪里不顺改哪里。</li></ol><h2 id="上手小例子" tabindex="-1">上手小例子 <a class="header-anchor" href="#上手小例子" aria-label="Permalink to &quot;上手小例子&quot;">​</a></h2><blockquote><p>你想做一个&quot;新人入职方案 Skill&quot;：</p><ul><li><strong>说明</strong>：给新同事出 30 天带教方案；</li><li><strong>步骤</strong>：①了解岗位和背景 → ②分四周排计划 → ③每周写目标和检查点 → ④输出方案；</li><li><strong>模板</strong>：四周计划表；</li><li><strong>检查点</strong>：目标是否可衡量、是否和岗位要求对齐。</li></ul></blockquote><h2 id="别踩的坑" tabindex="-1">别踩的坑 <a class="header-anchor" href="#别踩的坑" aria-label="Permalink to &quot;别踩的坑&quot;">​</a></h2><ul><li>❌ 一次想做十个 Skill——<strong>先做一个，做到好用</strong>；</li><li>❌ 只写&quot;原则&quot;不写&quot;动作&quot;——<strong>要能照着做，不是口号</strong>；</li><li>❌ 做完不试跑——<strong>没经过真任务检验的 Skill，先别推广</strong>。</li></ul><h2 id="一句话总结" tabindex="-1">一句话总结 <a class="header-anchor" href="#一句话总结" aria-label="Permalink to &quot;一句话总结&quot;">​</a></h2><p><strong>好 Skill = 说明 + 步骤 + 模板 + 检查点，来自你真正做过、做顺的事。</strong></p><h2 id="一分钟测试" tabindex="-1">一分钟测试 <a class="header-anchor" href="#一分钟测试" aria-label="Permalink to &quot;一分钟测试&quot;">​</a></h2><p>选一件你做得最好的重复性工作——<strong>它能不能写成&quot;新人照着做也能合格&quot;的清单？</strong> 能，就动手做你的第一个 Skill。</p><p>👉 [下一章：多 Agent 系统设计（易懂版）](第18章 如何进行多 Agent 系统设计（易懂版）.md)</p>',20)])])}const d=t(r,[["render",s]]);export{_ as __pageData,d as default};
